    16	export type Step = QuoteStep | ClaimStep;
    17	
    18	export interface Scenario {
    19	  customer: Customer;
    20	  steps: Step[];
    21	}
    22	
    23	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
