    25	export interface ScenarioResults {
    26	  results: StepResult[];
    27	}
    28	
    29	/**
    30	 * How the MHPCO works through a scenario: it takes the customer's steps in
    31	 * order, writing a policy for each quote and settling each claim against the
    32	 * policy the referenced quote step opened.
    33	 */
    34	export function runScenario(scenario: Scenario): ScenarioResults {
    35	  const policiesByStep = new Map<number, Policy>();
    36	  let previousQuoteCount = 0;
    37	
    38	  const results = scenario.steps.map((step, stepIndex): StepResult => {
    39	    if (step.op === "quote") {
    40	      const premium = quote(scenario.customer, step.items, previousQuoteCount);
    41	      previousQuoteCount += 1;
    42	      policiesByStep.set(stepIndex, openPolicy(step.items));
    43	      return { premium };
    44	    }
    45	
    46	    const policy = policiesByStep.get(step.policy);
    47	    if (policy === undefined) {
    48	      throw new Error(`Step ${step.policy} did not open a policy to claim against`);
    49	    }
    50	    const result = claim(policy, step.incident);
    51	    policiesByStep.set(step.policy, { ...policy, remainingCap: result.remainingCap });
    52	    return result;
    53	  });
    54	
    55	  return { results };
    56	}
