    13	  damages: Damage[];
    14	}
    15	
    16	export interface ClaimResult {
    17	  payout: number;
    18	  remainingCap: number;
    19	}
    20	
    21	/** A policy the MHPCO has written: the items it covers and the cap still available. */
    22	export interface Policy {
    23	  items: Item[];
    24	  remainingCap: number;
    25	}
    26	
    27	export function openPolicy(items: Item[]): Policy {
    28	  return { items, remainingCap: payoutCapOf(items) };
    29	}
    30	
    31	const DEDUCTIBLE_PER_DAMAGE_EVENT = 100;
    32	
    33	/** A damage entry together with the insured object it claims. */
    34	interface ClaimedDamage {
    35	  damage: Damage;
    36	  damagedItem: Item;
    37	}
    38	
    39	/**
    40	 * Whether the office will consider a damage report at all, judged from the
    41	 * report alone and before any policy is consulted: it refuses to read a report
    42	 * claiming an amount of damage that was never suffered.
    43	 */
    44	function admitDamageReport(damage: Damage): void {
    45	  if (damage.amount < 0) {
    46	    throw new Error(`A damage report cannot claim a negative amount of ${damage.amount} G`);
    47	  }
    48	}
    49	
    50	/**
    51	 * Which insured object an admitted damage entry claims. Each entry claims a
    52	 * covered object of its own, taking it out of the office's reckoning, so an
    53	 * incident cannot report more damaged objects of a type than the policy
    54	 * actually covers — and an object the policy never covered, whether an item
    55	 * type the office does not underwrite or one it simply did not insure here, is
    56	 * no more claimable than one already claimed.
    57	 */
    58	function claimAgainstCoverage(unclaimedItems: Item[], damage: Damage): Item {
    59	  const insuredIndex = unclaimedItems.findIndex((item) => item.type === damage.itemType);
    60	  if (insuredIndex === -1) {
    61	    throw new Error(`The policy does not cover a further item of type "${damage.itemType}"`);
    62	  }
    63	  return unclaimedItems.splice(insuredIndex, 1)[0];
    64	}
    65	
    66	/**
    67	 * How the office reads an incident's damage entries against a policy: it admits
    68	 * each report, then matches it to a covered object still unclaimed.
    69	 */
    70	function claimedDamagesOf(policy: Policy, damages: Damage[]): ClaimedDamage[] {
    71	  const unclaimedItems = [...policy.items];
    72	  return damages.map((damage) => {
    73	    admitDamageReport(damage);
    74	    return { damage, damagedItem: claimAgainstCoverage(unclaimedItems, damage) };
    75	  });
    76	}
    77	
    78	/**
    79	 * What one damaged item earns its owner: the share the settlement rulebook
    80	 * reimburses, less the deductible the office withholds for each damage event.
    81	 * The office reaches this figure for a damaged object on its own, which is why
    82	 * a second damaged object in the same incident is withheld its own deductible.
    83	 */
    84	function settlementFor(damage: Damage, damagedItem: Item): number {
    85	  return reimbursedShareOf(damage.amount, damagedItem) - DEDUCTIBLE_PER_DAMAGE_EVENT;
    86	}
    87	
    88	/**
    89	 * What the MHPCO owes for an incident before the policy's cap is consulted: it
    90	 * works out which insured object each damage entry claims, settles each claimed
    91	 * damage on its own, and rounds the total in the office's favour.
    92	 */
    93	function owedForIncident(policy: Policy, incident: Incident): number {
    94	  const settlements = claimedDamagesOf(policy, incident.damages).reduce(
    95	    (running, { damage, damagedItem }) => running + settlementFor(damage, damagedItem),
    96	    0,
    97	  );
    98	  return roundAmountOfficePays(settlements);
    99	}
   100	
   101	/**
   102	 * How the MHPCO settles an incident: it works out what it owes for the damages,
   103	 * then pays out only as far as the policy's remaining cap affords.
   104	 */
   105	export function claim(policy: Policy, incident: Incident): ClaimResult {
   106	  return drawFromCap(policy.remainingCap, owedForIncident(policy, incident));
   107	}
