     3	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
     4	
     5	/**
     6	 * The MHPCO's promise-ceiling rule: the office will ever pay out at most twice
     7	 * a policy's insurance sum, and it treats that ceiling as a finite balance —
     8	 * every payout draws the balance down, and once it is exhausted the office pays
     9	 * nothing more. Establishing the ceiling and drawing on it are the same office
    10	 * decision about how far its promise reaches, so they are stated together here.
    11	 */
    12	export function payoutCapOf(items: Item[]): number {
    13	  return policyInsuranceSum(items) * CAP_MULTIPLE_OF_INSURANCE_SUM;
    14	}
    15	
    16	/** What the cap still affords of a desired payout, and what is left afterwards. */
    17	export function drawFromCap(
    18	  remainingCap: number,
    19	  desiredPayout: number,
    20	): { payout: number; remainingCap: number } {
    21	  const affordable = Math.min(desiredPayout, remainingCap);
    22	  return { payout: affordable, remainingCap: remainingCap - affordable };
    23	}
