    10	/**
    11	 * The customer's standing with the MHPCO at the moment of a quote: how long the
    12	 * business relationship has lasted, and how many contracts preceded this one.
    13	 */
    14	export interface CustomerStanding {
    15	  customer: Customer;
    16	  previousQuoteCount: number;
    17	}
    18	
    19	/**
    20	 * The customer's standing at the moment of this quote, as the MHPCO reads it
    21	 * from the scenario so far: the business relationship and the contracts that
    22	 * preceded this one.
    23	 */
    24	export function standingOf(customer: Customer, previousQuoteCount: number): CustomerStanding {
    25	  return { customer, previousQuoteCount };
    26	}
    27	
    28	/** Whether this quote follows an earlier contract of the same customer. */
    29	function isFollowUpContract(standing: CustomerStanding): boolean {
    30	  return standing.previousQuoteCount >= 1;
    31	}
    32	
    33	/**
    34	 * Every item in a quote is treated as a first insurance, regardless of customer
    35	 * history, so the office levies the initial assessment on every policy.
    36	 */
    37	function isFirstInsurance(): boolean {
    38	  return true;
    39	}
    40	
    41	/** Whether the MHPCO regards the customer as long-standing. */
    42	function isLongStanding(standing: CustomerStanding): boolean {
    43	  return standing.customer.yearsWithMHPCO >= LOYALTY_YEARS;
    44	}
    45	
    46	/**
    47	 * A policy-wide clause of the MHPCO's rulebook: the condition under which the
    48	 * office grants or levies it, and the signed rate it charges on the policy base
    49	 * premium — positive for a surcharge, negative for a discount. Condition and
    50	 * rate belong to one clause and change together.
    51	 */
    52	interface PolicyWideClause {
    53	  appliesTo(standing: CustomerStanding): boolean;
    54	  rate: number;
    55	}
    56	
    57	/**
    58	 * The policy-wide clauses the MHPCO's rulebook currently contains: the initial
    59	 * assessment surcharge levied on every first insurance, the loyalty discount
    60	 * granted to a long-standing customer, and the follow-up discount granted on
    61	 * each contract after the customer's first.
    62	 */
    63	const POLICY_WIDE_CLAUSES: PolicyWideClause[] = [
    64	  { appliesTo: isFirstInsurance, rate: FIRST_INSURANCE_SURCHARGE_RATE },
    65	  { appliesTo: isLongStanding, rate: -LOYALTY_DISCOUNT_RATE },
    66	  { appliesTo: isFollowUpContract, rate: -FOLLOW_UP_DISCOUNT_RATE },
    67	];
