    71	 * base premium and never on an already-modified amount.
    72	 */
    73	export function policyWideModifiers(policyBase: number, standing: CustomerStanding): number {
    74	  return POLICY_WIDE_CLAUSES.filter((clause) => clause.appliesTo(standing)).reduce(
    75	    (running, clause) => running + policyBase * clause.rate,
    76	    0,
    77	  );
    78	}

