     7	
     8	/** The MHPCO price list for main items: one base premium per item type. */
     9	const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
    10	  sword: 100,
    11	  amulet: 60,
    12	  staff: 80,
    13	  potion: 40,
    14	};
    15	
    16	/** The MHPCO price list for main items: one insurance value per item type. */
    17	const MAIN_ITEM_INSURANCE_VALUES: Record<string, number> = {
    18	  sword: 1000,
    19	  amulet: 600,
    20	  staff: 800,
    21	  potion: 400,
    22	};
    23	
    24	/** Components (runes, moonstones) are all priced at the same rate per component. */
    25	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
    26	const COMPONENT_BASE_PREMIUM = 25;
    27	const COMPONENT_INSURANCE_VALUE = 250;
    28	const COMPONENT_BLOCK_SIZE = 3;
    29	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
    30	
    31	/** Whether the MHPCO prices this object as a component rather than a main item. */
    32	function isComponent(item: Item): boolean {
    33	  return COMPONENT_TYPES.has(item.type);
    34	}
    35	
    36	/**
    37	 * Which components the MHPCO considers "alike", and therefore eligible to form a
    38	 * block together: components of exactly the same type.
    39	 */
    40	function alikeComponentGroupKey(item: Item): string {
    41	  return item.type;
    42	}
    43	
    44	/**
    45	 * The MHPCO's coverage decision: a main item is covered only if its type appears
    46	 * in the office's price list, and an object the list does not name is refused.
    47	 * Every figure the list quotes for a main item is read through here, so the one
    48	 * rule about what the office covers is stated once.
    49	 */
    50	function listedMainItemFigure(pricelist: Record<string, number>, item: Item): number {
    51	  const listedFigure = pricelist[item.type];
    52	  if (listedFigure === undefined) {
    53	    throw new Error(`The MHPCO price list does not cover items of type "${item.type}"`);
    54	  }
    55	  return listedFigure;
    56	}
    57	
    58	/** The base premium the MHPCO charges for a single main item, per its price list. */
    59	function mainItemBasePremium(item: Item): number {
    60	  return listedMainItemFigure(MAIN_ITEM_BASE_PREMIUMS, item);
    61	}
    62	
    63	/** The sizes of the groups of alike components the policy covers. */
    64	function alikeComponentGroupSizes(components: Item[]): number[] {
    65	  const sizes = new Map<string, number>();
    66	  for (const component of components) {
    67	    const key = alikeComponentGroupKey(component);
    68	    sizes.set(key, (sizes.get(key) ?? 0) + 1);
    69	  }
    70	  return [...sizes.values()];
    71	}
    72	
    73	/**
    74	 * Alike components are offered as a block: a group of exactly the block size
    75	 * is charged the special block base premium instead of the per-component rate.
    76	 */
    77	function componentsBasePremium(count: number): number {
    78	  if (count === COMPONENT_BLOCK_SIZE) {
    79	    return COMPONENT_BLOCK_BASE_PREMIUM;
    80	  }
    81	  return count * COMPONENT_BASE_PREMIUM;
    82	}
    83	
    84	/**
    85	 * The amount an item-specific risk surcharge is levied on: the base premium the
    86	 * price list attaches to the single object, per its own rate. A component is
    87	 * rated per component here even when it sits in a block, because the block
    88	 * price is a property of the group rather than of any one component; the office
    89	 * has issued no rule for surcharging a component inside a block.
    90	 */
    91	export function surchargeableBasePremiumOf(item: Item): number {
    92	  if (isComponent(item)) {
    93	    return COMPONENT_BASE_PREMIUM;
    94	  }
    95	  return mainItemBasePremium(item);
    96	}
    97	
    98	function sum(amounts: number[]): number {
    99	  return amounts.reduce((running, amount) => running + amount, 0);
   100	}
   101	
   102	/**
   103	 * The policy base premium: the sum of the base premiums of all insured items,
   104	 * before any policy-wide modifier or the processing fee.
   105	 */
   106	export function policyBasePremium(items: Item[]): number {
   107	  const mainItems = items.filter((item) => !isComponent(item));
   108	  const components = items.filter(isComponent);
   109	  return (
   110	    sum(mainItems.map(mainItemBasePremium)) +
   111	    sum(alikeComponentGroupSizes(components).map(componentsBasePremium))
   112	  );
   113	}
   114	
   115	/** The value the MHPCO insures a single object for, per its price list. */
   116	export function insuranceValueOf(item: Item): number {
   117	  if (isComponent(item)) {
   118	    return COMPONENT_INSURANCE_VALUE;
   119	  }
   120	  return listedMainItemFigure(MAIN_ITEM_INSURANCE_VALUES, item);
   121	}
   122	
   123	/**
   124	 * The insurance sum of a policy: the sum of the insurance values of the items it
   125	 * covers. Premium discounts such as the component block do not reduce it.
   126	 */
   127	export function policyInsuranceSum(items: Item[]): number {
   128	  return sum(items.map(insuranceValueOf));
   129	}
