    17	/**
    18	 * A risk surcharge clause of the MHPCO's underwriting rulebook: the condition
    19	 * under which the office judges an object risky, and the rate it charges for
    20	 * that risk. Condition and rate belong to one clause and change together.
    21	 */
    22	interface RiskSurchargeClause {
    23	  appliesTo(item: Item): boolean;
    24	  rate: number;
    25	}
