    28	const RISK_SURCHARGE_CLAUSES: RiskSurchargeClause[] = [
    29	  { appliesTo: isCursed, rate: CURSE_SURCHARGE_RATE },
    30	  { appliesTo: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
    31	];
    32	
    33	/** The rates of the risk surcharges an individual object attracts. */
    34	function riskSurchargeRates(item: Item): number[] {
    35	  return RISK_SURCHARGE_CLAUSES.filter((clause) => clause.appliesTo(item)).map(
    36	    (clause) => clause.rate,
    37	  );
    38	}
    39	
    40	/**
    41	 * Item-specific risk surcharges: the MHPCO's underwriting judgement about how
    42	 * risky an individual object is. Each surcharge is levied on the base premium
    43	 * of the affected item alone, never on the policy total. Which amount that is
    44	 * belongs to the price list, not to the underwriting rulebook, so it is asked
    45	 * for rather than derived here.
    46	 */
    47	function itemRiskSurcharge(item: Item): number {
    48	  const itemBase = surchargeableBasePremiumOf(item);
    49	  return riskSurchargeRates(item).reduce((running, rate) => running + itemBase * rate, 0);
