     1	import { type Item } from "./item-pricing.js";
     2	
     3	const SEVERE_ENCHANTMENT_LEVEL = 8;
     4	const SEVERE_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
     5	const DRAGON_MATERIAL = "dragon";
     6	const FULL_REIMBURSEMENT_RATE = 1;
     7	
     8	/** Whether the MHPCO's severe-enchantment clause covers this damaged object. */
     9	function isSeverelyEnchanted(item: Item): boolean {
    10	  return (item.enchantment ?? 0) >= SEVERE_ENCHANTMENT_LEVEL;
    11	}
    12	
    13	/** Whether the MHPCO's dragon-material clause covers this damaged object. */
    14	function isDragonMaterial(item: Item): boolean {
    15	  return item.material === DRAGON_MATERIAL;
    16	}
    17	
    18	/**
    19	 * A reimbursement clause of the MHPCO's settlement rulebook: the condition
    20	 * under which the office applies it, and the share of the damage it reimburses.
    21	 * Condition and share belong to one clause and change together. The clauses are
    22	 * listed in the order the office resolves them: where several clauses cover the
    23	 * same damage, the first listed wins.
    24	 */
    25	interface ReimbursementClause {
    26	  appliesTo(item: Item): boolean;
    27	  share: number;
    28	}
    29	
    30	const REIMBURSEMENT_CLAUSES: ReimbursementClause[] = [
    31	  { appliesTo: isSeverelyEnchanted, share: SEVERE_ENCHANTMENT_REIMBURSEMENT_RATE },
    32	  { appliesTo: isDragonMaterial, share: FULL_REIMBURSEMENT_RATE },
    33	];
    34	
    35	/**
    36	 * The share of a damage the MHPCO's settlement rulebook reimburses: the share
    37	 * of the first clause that covers the damaged object, or full reimbursement
    38	 * when no clause does. This is the office's judgement about what it owes for
    39	 * the damage itself, before the deductible and the cap the policy imposes.
    40	 */
    41	export function reimbursedShareOf(damageAmount: number, damagedItem: Item): number {
    42	  const clause = REIMBURSEMENT_CLAUSES.find((candidate) => candidate.appliesTo(damagedItem));
    43	  return damageAmount * (clause?.share ?? FULL_REIMBURSEMENT_RATE);
    44	}

